async def act(page):
    """
    Navigate to the Magento Admin Bestsellers report, set Period=Quarter and Q1 2022
    (or fallback to From/To dates covering Q1 2022), run the report, and return the
    top-1 bestselling product (the first product name) as a plain string.

    Notes about the knowledge-base helpers:
    - I examined the provided KB helpers (dashboard- and orders-focused). None of
      them provide navigation or controls for the Reports -> Products -> Bestsellers
      page or selecting a Quarter + specific quarter/year. Therefore none are used.
    """
    # Navigate to the Bestsellers report page (relative path)
    await page.goto('/index.php/admin/report_product/bestsellers/')
    await page.wait_for_load_state('networkidle')
    await page.wait_for_timeout(700)

    # Helper: safely read option texts for a combobox locator
    async def _option_texts_for(cb):
        try:
            opts = cb.get_by_role('option')
            if await opts.count() == 0:
                return []
            return await opts.all_inner_texts()
        except Exception:
            return []

    # 1) Try to set a Period combobox to 'Quarter'
    comboboxes = page.get_by_role('combobox')
    if await comboboxes.count() > 0:
        for i in range(await comboboxes.count()):
            cb = comboboxes.nth(i)
            option_texts = await _option_texts_for(cb)
            for opt in option_texts:
                if opt and 'quarter' in opt.lower():
                    try:
                        await cb.select_option(label=opt)
                    except Exception:
                        pass
                    # attempted to set period; break out for this combobox
                    break

    # 2) Attempt to select Q1 2022 explicitly in any combobox
    quarter_selected = False
    comboboxes = page.get_by_role('combobox')
    if await comboboxes.count() > 0:
        for i in range(await comboboxes.count()):
            cb = comboboxes.nth(i)
            option_texts = await _option_texts_for(cb)
            target_label = None
            for opt in option_texts:
                low = (opt or '').lower()
                if 'q1' in low and '2022' in low:
                    target_label = opt
                    break
            if not target_label:
                for opt in option_texts:
                    if opt and 'q1' in opt.lower():
                        target_label = opt
                        break
            if not target_label:
                for opt in option_texts:
                    if opt and '2022' in opt:
                        target_label = opt
                        break
            if target_label:
                try:
                    await cb.select_option(label=target_label)
                    quarter_selected = True
                except Exception:
                    pass
            if quarter_selected:
                break

    # 3) Fallback: fill From/To date fields to cover Q1 2022
    if not quarter_selected:
        try:
            from_tb = page.get_by_role('textbox', name='From')
            if await from_tb.count() > 0:
                await from_tb.first.fill('01/01/2022')
        except Exception:
            try:
                tbs = page.get_by_role('textbox')
                for j in range(await tbs.count()):
                    tb = tbs.nth(j)
                    try:
                        nm = await tb.get_attribute('name')
                    except Exception:
                        nm = None
                    if nm and 'from' in nm.lower():
                        await tb.fill('01/01/2022')
                        break
            except Exception:
                pass
        try:
            to_tb = page.get_by_role('textbox', name='To')
            if await to_tb.count() > 0:
                await to_tb.first.fill('03/31/2022')
        except Exception:
            try:
                tbs = page.get_by_role('textbox')
                for j in range(await tbs.count()):
                    tb = tbs.nth(j)
                    try:
                        nm = await tb.get_attribute('name')
                    except Exception:
                        nm = None
                    if nm and 'to' in nm.lower():
                        await tb.fill('03/31/2022')
                        break
            except Exception:
                pass

    # 4) Click the 'Show Report' (or equivalent) button
    show_button = None
    candidate_names = ['Show Report', 'Show', 'Refresh', 'Filter', 'Search', 'Submit', 'Go', 'Apply']
    for name in candidate_names:
        btn = page.get_by_role('button', name=name)
        if await btn.count() > 0:
            show_button = btn.first
            break
    if not show_button:
        all_buttons = page.get_by_role('button')
        if await all_buttons.count() > 0:
            show_button = all_buttons.first

    if show_button:
        try:
            await show_button.click()
        except Exception:
            try:
                tbs = page.get_by_role('textbox')
                if await tbs.count() > 0:
                    await tbs.first.press('Enter')
            except Exception:
                pass
    else:
        try:
            await page.keyboard.press('Enter')
        except Exception:
            pass

    # 5) Wait for results and extract top-1 product
    await page.wait_for_timeout(1200)
    tables = page.get_by_role('table')
    if await tables.count() == 0:
        # fallback: read document first non-empty line
        try:
            doc = page.get_by_role('document')
            if await doc.count() > 0:
                text = await doc.first.inner_text()
                for line in (ln.strip() for ln in text.splitlines() if ln.strip()):
                    return line
        except Exception:
            pass
        raise RuntimeError('No results table or fallback text found on Bestsellers report page')

    table = tables.first
    rows = table.get_by_role('row')
    if await rows.count() == 0:
        raise RuntimeError('No rows found in results table')

    if await rows.count() > 1:
        data_row = rows.nth(1)
    else:
        data_row = rows.nth(0)

    cells = data_row.get_by_role('cell')
    if await cells.count() > 0:
        top1 = (await cells.first.inner_text()).strip()
        return top1
    else:
        return (await data_row.inner_text()).strip()

